package com.aac.ieojwo.alert.controller;
import com.aac.ieojwo.alert.service.AlertService;import com.aac.ieojwo.alert.service.AlertService.AlertResponse;import com.aac.ieojwo.common.api.ApiResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/me")
public class AlertController{public record SubscriptionRequest(@NotBlank String endpoint,@NotBlank String p256dh,@NotBlank String auth){}private final AlertService service;public AlertController(AlertService service){this.service=service;}@PostMapping("/push-subscriptions")public ApiResponse<Map<String,Long>> subscribe(@AuthenticationPrincipal OidcUser p,@Valid @RequestBody SubscriptionRequest r){return ApiResponse.ok(Map.of("id",service.subscribe(p,r.endpoint(),r.p256dh(),r.auth())));}@GetMapping("/aac-users/{userId}/alerts")public ApiResponse<List<AlertResponse>> alerts(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestParam Instant from,@RequestParam Instant to){return ApiResponse.ok(service.list(p,userId,from,to));}@PostMapping("/aac-users/{userId}/alerts/{alertId}/acknowledge")public ApiResponse<AlertResponse> ack(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@PathVariable Long alertId){return ApiResponse.ok(service.acknowledge(p,userId,alertId));}}
